var b = a
b.box.value = 9
b.count = 9
print(a.box.value, a.count)

protocol Greeter {
  func greet()
}
extension Greeter {
  func greet() { print("Hello") }
  func wave() { print("Wave from protocol") }
}
struct Robot: Greeter {
  func greet() { print("Beep") }
  func wave() { print("Robot waves") }
}
let g: any Greeter = Robot()
g.greet()
g.wave()

func largest<T>(_ items: [T]) -> T? {
  guard var best = items.first else { return nil }
  for item in items where item > best {
    best = item
  }
  return best
}
print(largest([3, 9, 4]) ?? 0)

protocol Describable {
  var name: String { get }
  func describe() -> String
}
extension Describable {
  func describe() -> String { "I am \(name)" }
}
struct Cat: Describable {
  let name = "Tom"
}
print(Cat().describe())

