final class ViewModel {
  var count = 0
  var onTap: (() -> Void)?
  init() {
    onTap = {
      self.count += 1
    }
  }
  deinit { print("deinit") }
}
var vm: ViewModel? = ViewModel()
vm?.onTap?()
vm = nil
print("done")

import Dispatch
