queue.async { print("2", terminator: " ") }
queue.sync { print("3", terminator: " ") }
print("4")

import Foundation
func loadConfig() -> String {
  DispatchQueue.main.sync {
    return "config"
  }
}
print("start")
print(loadConfig())

// logToServer(_:) is an async network call
actor BankAccount {
  var balance = 100
  func withdraw(_ amount: Int) async -> Bool {
    guard balance >= amount else { return false }
    await logToServer(amount)
    balance -= amount
    return true
  }
}

func countItems() async -> Int {
  var total = 0
  await withTaskGroup(of: Void.self) { group in
    for _ in 0..<100 {
      group.addTask {
        total += 1
      }
    }
  }
  return total
}

@MainActor
final class ProfileModel: ObservableObject {
  @Published var name = ""
  func load() async { name = "An" }
}

struct ProfileScreen: View {
  @ObservedObject var model = ProfileModel()

  var body: some View {
    Text(model.name)
      .task { await model.load() }
  }
}
